import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.e4u2V5E7.js";const g=JSON.parse('{"title":"Vector Databases","description":"Vector Databases reference documentation","frontmatter":{"title":"Vector Databases","description":"Vector Databases reference documentation"},"headers":[],"relativePath":"knowledge/vector-databases.md","filePath":"knowledge/vector-databases.md","lastUpdated":1784485118000}'),s={name:"knowledge/vector-databases.md"};function n(o,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="vector-databases" tabindex="-1">Vector Databases <a class="header-anchor" href="#vector-databases" aria-label="Permalink to &quot;Vector Databases&quot;">​</a></h1><h1 id="vector-databases-—-knowledge-base" tabindex="-1">Vector Databases — Knowledge Base <a class="header-anchor" href="#vector-databases-—-knowledge-base" aria-label="Permalink to &quot;Vector Databases — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Vector databases store and query high-dimensional vectors (embeddings) efficiently. They enable semantic search, similarity matching, and RAG by finding vectors that are closest to a query vector. This knowledge base compares vector database options, indexing strategies, and optimization patterns.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="vector-database-comparison" tabindex="-1">Vector Database Comparison <a class="header-anchor" href="#vector-database-comparison" aria-label="Permalink to &quot;Vector Database Comparison&quot;">​</a></h3><p><strong>Pinecone</strong> — Fully managed cloud vector database.</p><ul><li>Pros: Zero-ops, automatic scaling, strong performance, metadata filtering</li><li>Cons: Vendor lock-in, cost at scale, limited customization</li><li>Best for: Teams that want managed infrastructure without DevOps</li></ul><p><strong>Weaviate</strong> — Open-source vector database with GraphQL API.</p><ul><li>Pros: Rich filtering, hybrid search built-in, module system, self-hostable</li><li>Cons: Operational complexity for self-hosting, memory usage</li><li>Best for: Teams needing hybrid search and customization</li></ul><p><strong>pgvector (Supabase)</strong> — PostgreSQL extension for vector storage.</p><ul><li>Pros: No new infrastructure, SQL interface, ACID transactions, Supabase integration</li><li>Cons: Slower than dedicated vector DBs at very large scale, limited vector-specific features</li><li>Best for: Teams already using PostgreSQL/Supabase, small-to-medium datasets</li></ul><p><strong>Qdrant</strong> — Open-source vector database written in Rust.</p><ul><li>Pros: High performance, rich filtering, gRPC support, easy deployment</li><li>Cons: Smaller community, fewer managed options</li><li>Best for: Performance-critical applications with self-hosting capability</li></ul><p><strong>Chroma</strong> — Open-source embedding database designed for simplicity.</p><ul><li>Pros: Easy to start, Python-native, good for prototyping</li><li>Cons: Limited scalability, fewer production features</li><li>Best for: Prototyping and development</li></ul><h3 id="indexing-algorithms" tabindex="-1">Indexing Algorithms <a class="header-anchor" href="#indexing-algorithms" aria-label="Permalink to &quot;Indexing Algorithms&quot;">​</a></h3><p><strong>HNSW (Hierarchical Navigable Small World)</strong> Graph-based algorithm creating a multi-layered navigation structure.</p><ul><li>Pros: Fast queries (O(log n)), high recall, good for dynamic data</li><li>Cons: Memory-intensive, slower index building</li><li>Used by: Most vector databases (default in Pinecone, Weaviate, Qdrant)</li></ul><p><strong>IVF (Inverted File Index)</strong> Partitions vectors into clusters (Voronoi cells); searches only nearby clusters.</p><ul><li>Pros: Memory-efficient, fast index building, good for static data</li><li>Cons: Lower recall than HNSW, requires cluster retraining</li><li>Used by: pgvector, Milvus</li></ul><p><strong>Flat (Brute Force)</strong> Compares query against every vector. Exact results.</p><ul><li>Pros: 100% recall, simple implementation</li><li>Cons: Slow for large datasets (O(n) per query)</li><li>Best for: Small datasets (&lt;10K vectors) or as baseline</li></ul><h3 id="metadata-filtering" tabindex="-1">Metadata Filtering <a class="header-anchor" href="#metadata-filtering" aria-label="Permalink to &quot;Metadata Filtering&quot;">​</a></h3><p>Attach structured data to vectors and filter during search:</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- pgvector example</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> embeddings</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> content_vector </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> metadata</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;category&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;documentation&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> metadata</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;language&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ar&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> content_vector </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="hybrid-search" tabindex="-1">Hybrid Search <a class="header-anchor" href="#hybrid-search" aria-label="Permalink to &quot;Hybrid Search&quot;">​</a></h3><p>Combine vector similarity with keyword matching:</p><p><strong>Reciprocal Rank Fusion (RRF):</strong> Merge rankings from vector and keyword search using reciprocal rank scores.</p><p><strong>Linear combination:</strong> Weighted sum of vector similarity score and keyword relevance score.</p><h3 id="performance-tuning" tabindex="-1">Performance Tuning <a class="header-anchor" href="#performance-tuning" aria-label="Permalink to &quot;Performance Tuning&quot;">​</a></h3><p><strong>Index parameters:</strong> HNSW <code>ef_construction</code> (build quality), <code>m</code> (connections per node), <code>ef_search</code> (query accuracy)</p><p><strong>Chunk size affects performance:</strong> Smaller chunks = more vectors = slower search but more precise matching.</p><p><strong>Distance metric affects speed:</strong> Cosine similarity requires normalized vectors; dot product is faster for pre-normalized data.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Start with pgvector if using Supabase</strong> — No new infrastructure needed; upgrade to dedicated vector DB if performance requires it</li><li><strong>Choose HNSW for most use cases</strong> — Best balance of speed and recall; tune <code>ef_search</code> for accuracy vs speed tradeoff</li><li><strong>Implement hybrid search</strong> — Combine vector and keyword search; catches both semantic and exact matches</li><li><strong>Filter by metadata before vector search</strong> — Narrow the search space with metadata filters; faster and more relevant results</li><li><strong>Batch index operations</strong> — Insert vectors in batches of 100-1000; bulk operations are much faster than individual inserts</li><li><strong>Monitor index size and query latency</strong> — Track vector count, memory usage, and p95 query latency; set alerts for degradation</li><li><strong>Use appropriate dimensions</strong> — Higher dimensions improve accuracy but increase storage and search time; profile different sizes</li><li><strong>Implement proper backup strategy</strong> — Vector data is expensive to regenerate; ensure backups include embeddings and metadata</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Choosing based on benchmarks alone</strong> — Benchmark results may not reflect your workload; test with your actual data and queries</li><li><strong>Ignoring metadata schema design</strong> — Poorly structured metadata limits filtering capability; plan metadata schema before indexing</li><li><strong>Over-indexing</strong> — Too many indexes slow writes and consume memory; only index fields used in filters</li><li><strong>Using vector search for exact matches</strong> — For exact ID lookups or exact text matching, use traditional database queries instead</li><li><strong>Not planning for scale</strong> — Vector databases grow fast; plan storage, memory, and query capacity for 10x your current size</li><li><strong>Ignoring embedding updates</strong> — When embedding models change, all vectors must be re-generated; plan for model migration</li><li><strong>Mixing incompatible metrics</strong> — Using cosine similarity for one search and dot product for another in the same index causes inconsistent results</li><li><strong>Skipping connection pooling</strong> — Each vector search creates connections; use connection pooling for production workloads</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not creating vector indexes</strong> — Without an index, every query does brute-force search; always create an HNSW or IVF index</li><li><strong>Using wrong distance metric for normalized vectors</strong> — If embeddings are normalized, cosine and dot product give identical rankings; pick one consistently</li><li><strong>Forgetting about memory</strong> — Vector databases are memory-intensive; 1M vectors × 1536 dimensions × 4 bytes ≈ 6GB RAM</li><li><strong>Not testing with production data size</strong> — Small test datasets don&#39;t reveal performance issues; test with production-scale data</li><li><strong>Ignoring query latency requirements</strong> — If you need &lt;100ms responses, test vector search under load with realistic data</li><li><strong>Hardcoding index parameters</strong> — Default parameters may not be optimal; tune HNSW <code>m</code> and <code>ef_construction</code> for your data</li><li><strong>Not implementing data lifecycle</strong> — Old or irrelevant vectors accumulate; implement deletion policies and TTL where appropriate</li><li><strong>Mixing vector and relational data without planning</strong> — Joining vector search results with relational data requires careful schema design</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dataset Size</th><th>Recommendation</th></tr></thead><tbody><tr><td>&lt; 10K vectors</td><td>pgvector (no new infrastructure)</td></tr><tr><td>10K - 1M vectors</td><td>pgvector with HNSW index or Qdrant</td></tr><tr><td>1M - 10M vectors</td><td>Pinecone, Weaviate, or Qdrant</td></tr><tr><td>&gt; 10M vectors</td><td>Pinecone (managed) or Weaviate cluster</td></tr><tr><td>Prototyping</td><td>Chroma or pgvector</td></tr><tr><td>Already on Supabase</td><td>pgvector first, migrate later if needed</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Requirement</th><th>Database Choice</th></tr></thead><tbody><tr><td>Zero operations</td><td>Pinecone</td></tr><tr><td>Hybrid search</td><td>Weaviate or pgvector</td></tr><tr><td>SQL interface</td><td>pgvector</td></tr><tr><td>Maximum speed</td><td>Qdrant or Pinecone</td></tr><tr><td>Self-hosted</td><td>Weaviate, Qdrant, or pgvector</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Pinecone Documentation: <a href="https://docs.pinecone.io/" target="_blank" rel="noreferrer">https://docs.pinecone.io/</a></li><li>Weaviate Documentation: <a href="https://weaviate.io/developers/weaviate" target="_blank" rel="noreferrer">https://weaviate.io/developers/weaviate</a></li><li>pgvector Documentation: <a href="https://github.com/pgvector/pgvector" target="_blank" rel="noreferrer">https://github.com/pgvector/pgvector</a></li><li>Qdrant Documentation: <a href="https://qdrant.tech/documentation/" target="_blank" rel="noreferrer">https://qdrant.tech/documentation/</a></li><li>Vector Database Comparison: <a href="https://superlinked.com/vector-db-comparison" target="_blank" rel="noreferrer">https://superlinked.com/vector-db-comparison</a></li><li>HNSW Paper: <a href="https://arxiv.org/abs/1603.09320" target="_blank" rel="noreferrer">https://arxiv.org/abs/1603.09320</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Supabase pgvector setup:</strong> Enable the <code>vector</code> extension; create table with <code>vector(1536)</code> column; add HNSW index</li><li><strong>Index creation in pgvector:</strong> <code>CREATE INDEX ON documents USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);</code></li><li><strong>Query performance:</strong> pgvector with HNSW typically achieves &lt;50ms for 1M vectors; test with your actual data</li><li><strong>Cost comparison:</strong> pgvector on Supabase Pro ($25/mo) vs Pinecone Starter ($0) vs Pinecone Standard ($70/mo)</li><li><strong>Migration path:</strong> Start with pgvector; if performance limits are hit, migrate to Qdrant or Pinecone with data export/import</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,49)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
